    lbu t6, 7(t0) # twist digit, '1'..'3'
    addi t6, t6, -49
    sltiu a1, t6, 3
    beqz a1, invalid
    add t4, t4, t6 # sum <= 2 + 2, one subtract reduces it
    addi a1, t4, -3
    bltz a1, parse_sum_ok
    mv t4, a1
parse_sum_ok:
    li a1, 6
    beq t2, a1, parse_next # the seventh twist is implied, not ranked
    slli a2, a3, 1 # a3 = a3 * 3 + twist
    add a3, a2, a3
    add a3, a3, t6
parse_next:
    addi t0, t0, 1
    addi t1, t1, 1
    addi t2, t2, 1
    li a1, 7
    bne t2, a1, parse
    lbu t5, 7(t0) # input[14] must end the string
    bnez t5, invalid
    bnez t4, invalid # twist sum must be 0 modulo 3
    la t0, digits # t0 = &digits[i], i = 0
    addi t2, t0, 6 # outer stop: digits + 6, so i = 0..5
    addi t6, t0, 7 # inner stop: digits + 7, so j reaches 6
    la t3, counts # t3 = &counts[i]
count_digit:
    lbu t5, 0(t0) # cur = digits[i]
    addi t1, t0, 1 # t1 = &digits[j], j = i + 1
    li a5, 0 # count = 0
count_later:
    bgeu t1, t6, count_stored # j = 7: nothing left to compare
    lbu a1, 0(t1) # a1 = digits[j]
    sltu a1, a1, t5 # a1 = 1 if digits[j] < cur, else 0
    add a5, a5, a1 # count += a1, no branch needed
    addi t1, t1, 1 # j++
    j count_later
count_stored:
    sb a5, 0(t3) # counts[i] = count
    addi t0, t0, 1 # i++ on the digits side
    addi t3, t3, 1 # i++ on the counts side
    bltu t0, t2, count_digit # i < 6: next digit
    la t3, counts # t3 = &counts[0], A left it at counts + 6
    lbu a2, 0(t3) # r = counts[0]
    slli t0, a2, 1 # t0 = 2r
    add t0, t0, a2 # t0 = 3r
    slli a2, t0, 1 # r = 6r, as 3r * 2
    lbu a5, 1(t3)
    add a2, a2, a5 # r = 6r + counts[1]
    slli t0, a2, 2 # t0 = 4r
    add a2, t0, a2 # r = 5r, as 4r + r
    lbu a5, 2(t3)
    add a2, a2, a5 # r = 5r + counts[2]
    slli a2, a2, 2 # r = 4r
    lbu a5, 3(t3)
    add a2, a2, a5 # r = 4r + counts[3]
    slli t0, a2, 1 # t0 = 2r
    add a2, a2, t0 # r = 3r, as r + 2r
    lbu a5, 4(t3)
    add a2, a2, a5 # r = 3r + counts[4]
    slli a2, a2, 1 # r = 2r
    lbu a5, 5(t3)
    add a2, a2, a5 # r = 2r + counts[5], the permutation rank
    slli gp, a2, 1 # root permutation rank, scaled by 2
    slli tp, a3, 1 # root orientation rank, scaled by 2
    la s0, perm_turn
    la s1, ori_turn
    la s2, perm_pdb
    la s3, ori_pdb
    la s4, perimeter_offset
    la s5, perimeter_entry
    la s8, frames
    li s11, 10080
    li a0, 0 # path length if the root is solved
    add t0, s2, gp
    lhu t0, 0(t0)
    add t1, s3, tp
    lhu t1, 0(t1)
    bgeu t0, t1, root_h
    mv t0, t1
root_h:
    beqz t0, report # solved already
    li t1, 5
    bltu t1, t0, root_bound # h0 above the radius: not in the perimeter
    mv a2, gp
    mv a3, tp
    jal ra, perimeter_lookup # t0 = exact distance, or radius + 1
root_bound:
    mv s6, t0
pass:
    li t0, 12
    bgeu s6, t0, no_solution # nothing within 11 moves: invalid input
    mv s7, s8
    addi a6, s6, -1
    mv a4, gp
    mv a5, tp
    mv a2, gp
    mv a3, tp
    li a0, 0
    li a1, 0
    li a7, 3
    mv s9, s0
    mv s10, s1
child:
    add t0, s9, a2
    lhu a2, 0(t0) # perm rank after the turn (scaled)
    add t1, s10, a3
    lhu a3, 0(t1) # ori rank after the turn (scaled)
    add t0, s2, a2
    lhu t0, 0(t0)
    add t1, s3, a3
    lhu t1, 0(t1)
    bgeu t0, t1, child_h
    mv t0, t1 # t0 = h0 = max of the two lookups
child_h:
    beqz t0, found # h0 == 0 only at solved
    bltu a6, t0, next # h0 > moves left: prune
    li t1, 6
    bgeu a6, t1, descend
    add t2, s4, a2
    lhu t3, 0(t2) # byte offsets into perimeter_entry
    lhu t4, 2(t2)
    add t3, s5, t3 # first entry of the bucket
    add t4, s5, t4 # one past the last
    slli t5, a3, 2
child_scan:
    bgeu t3, t4, next # bucket exhausted: absent, prune
    lhu t6, 0(t3)
    addi t3, t3, 2
    bltu t6, t5, child_scan # ori below o: keep scanning
    sub t0, t6, t5 # distance on a match, >= 8 past it
    bltu a6, t0, next # more than the moves left: prune
descend:
    sw s9, 0(s7)
    sw s10, 4(s7)
    sh a4, 8(s7)
    sh a5, 10(s7)
    sb a0, 16(s7)
    sb a1, 17(s7)
    addi s7, s7, 32
    addi a6, a6, -1
    mv a7, a0 # the face just used
    mv a4, a2
    mv a5, a3
    li a0, 0
    li a1, 0
    mv s9, s0
    mv s10, s1
    bnez a7, child # face 0 allowed unless it was just used
    li a0, 1
    add s9, s0, s11
    addi s10, s1, 1458
    j child
next:
    addi a1, a1, 1
    li t0, 3 # still 3 in next_face: nothing there writes t0
    bne a1, t0, child
    li a1, 0
next_face:
    addi a0, a0, 1
    add s9, s9, s11
    addi s10, s10, 1458
    beq a0, t0, backtrack # test before the skip: the root sentinel is 3
    beq a0, a7, next_face
    mv a2, a4
    mv a3, a5
    j child
backtrack:
    beq s7, s8, pass_failed
    addi s7, s7, -32
    addi a6, a6, 1
    mv a2, a4 # the child descended into is the node just left
    mv a3, a5
    lw s9, 0(s7)
    lw s10, 4(s7)
    lhu a4, 8(s7)
    lhu a5, 10(s7)
    lbu a0, 16(s7)
    lbu a1, 17(s7)
    lbu a7, -16(s7) # face of the depth above (sentinel: 3)
    j next
pass_failed:
    addi s6, s6, 1
    j pass
found:
    la t2, moves
    mv t3, s8
copy_move:
    beq t3, s7, copy_last
    lbu t0, 16(t3) # move = face * 3 + turns
    slli t1, t0, 1
    add t0, t1, t0
    lbu t1, 17(t3)
    add t0, t0, t1
    sb t0, 0(t2)
    addi t2, t2, 1
    addi t3, t3, 32
    j copy_move
copy_last:
    slli t1, a0, 1
    add t0, t1, a0
    add t0, t0, a1
    sb t0, 0(t2)
    la t0, moves
    sub a0, t2, t0
    addi a0, a0, 1 # path length
report:
    mv s6, a0 # s6 = length from here on
    la s7, moves
    add s8, s7, s6 # end of moves
    li s9, 0 # moves printed
print_move:
    beq s7, s8, print_done
    beqz s9, print_name
    li a0, 32 # space
    li a7, 11
    ecall
print_name:
    lbu t0, 0(s7)
    slli t0, t0, 2
    la a0, names
    add a0, a0, t0
    li a7, 4
    ecall
    addi s7, s7, 1
    addi s9, s9, 1
    j print_move
print_done:
    la a0, msg_newline
    li a7, 4
    ecall
    mv a2, gp
    mv a3, tp
    la s7, moves
replay:
    beq s7, s8, replay_done
    lbu t0, 0(s7)
    mv t1, s0 # perm row of the face, t0 = turns - 1
    mv t2, s1
replay_face:
    li t3, 3
    bltu t0, t3, replay_turn
    addi t0, t0, -3
    add t1, t1, s11
    addi t2, t2, 1458
    j replay_face
replay_turn:
    add t3, t1, a2
    lhu a2, 0(t3)
    add t3, t2, a3
    lhu a3, 0(t3)
    addi t0, t0, -1
    bgez t0, replay_turn
    addi s7, s7, 1
    j replay
replay_done:
    or t0, a2, a3
    bnez t0, report_fail
    li t0, 2
    bne s6, t0, report_fail
    la a0, msg_ok
    j report_length
report_fail:
    la a0, msg_fail
report_length:
    li a7, 4
    ecall
    mv a0, s6
    li a7, 1
    ecall
    la a0, msg_newline
    li a7, 4
    ecall
    j exit
invalid:
no_solution:
    la a0, msg_invalid
    li a7, 4
    ecall
exit:
    li a7, 10
    ecall
perimeter_lookup:
    add t2, s4, a2
    lhu t3, 0(t2) # byte offsets into perimeter_entry
    lhu t4, 2(t2)
    add t3, s5, t3 # first entry of the bucket
    add t4, s5, t4 # one past the last
    slli t5, a3, 2
lookup_scan:
    bgeu t3, t4, lookup_miss
    lhu t6, 0(t3)
    addi t3, t3, 2
    bltu t6, t5, lookup_scan # ori below o: keep scanning
    sub t0, t6, t5 # equal ori leaves just the distance
    li t6, 8
    bltu t0, t6, lookup_done
lookup_miss:
    li t0, 6
lookup_done:
    ret
